// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (e.g. 200 for unknown order). Don't "fix" these without intent.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 2.5, gold: 150 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (path, body, raw = false) =>
  fetch(base + path, { method: 'POST', body: raw ? body : JSON.stringify(body) })
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order and returns 201 JSON', async () => {
  const r = await json(await post('/orders', { items: [{ sku: 'apple', qty: 2 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, { id: r.body.id, items: [{ sku: 'apple', qty: 2 }], total: 20 })
  assert.equal(typeof r.body.id, 'string')
})

test('order ids are sequential strings', async () => {
  const a = (await json(await post('/orders', { items: [{ sku: 'apple', qty: 1 }] }))).body.id
  const b = (await json(await post('/orders', { items: [{ sku: 'apple', qty: 1 }] }))).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('total sums price * qty across items', async () => {
  const r = await json(await post('/orders', { items: [{ sku: 'apple', qty: 3 }, { sku: 'pear', qty: 4 }] }))
  assert.equal(r.body.total, 40)
})

test('total is floored to a whole number', async () => {
  const r = await json(await post('/orders', { items: [{ sku: 'pear', qty: 3 }] }))
  assert.equal(r.body.total, 7) // 7.5
})

test('no discount at exactly 100', async () => {
  const r = await json(await post('/orders', { items: [{ sku: 'apple', qty: 10 }] }))
  assert.equal(r.body.total, 100)
})

test('10% discount applies when total is over 100', async () => {
  const r = await json(await post('/orders', { items: [{ sku: 'apple', qty: 11 }] }))
  assert.equal(r.body.total, 99) // 110 - 11
  const g = await json(await post('/orders', { items: [{ sku: 'gold', qty: 1 }] }))
  assert.equal(g.body.total, 135)
})

test('discounted total is floored', async () => {
  const r = await json(await post('/orders', { items: [{ sku: 'pear', qty: 41 }] }))
  assert.equal(r.body.total, 92) // 102.5 * 0.9 = 92.25
})

test('GET /orders/:id returns a created order', async () => {
  const created = (await json(await post('/orders', { items: [{ sku: 'apple', qty: 1 }] }))).body
  const r = await json(await fetch(`${base}/orders/${created.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created)
})

test('GET unknown order returns 200 with error body (not 404)', async () => {
  const r = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

for (const [name, body] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['non-array items', { items: 'apple' }],
]) {
  test(`POST /orders with ${name} -> 400`, async () => {
    const r = await json(await post('/orders', body))
    assert.equal(r.status, 400)
    assert.deepEqual(r.body, { error: 'items required' })
  })
}

test('POST /orders with invalid JSON -> 400', async () => {
  const r = await json(await post('/orders', '{not json', true))
  assert.equal(r.status, 400)
  assert.deepEqual(r.body, { error: 'items required' })
})

test('invalid orders are not stored', async () => {
  const before = (await json(await post('/orders', { items: [{ sku: 'apple', qty: 1 }] }))).body.id
  await post('/orders', { items: [] })
  const after = (await json(await post('/orders', { items: [{ sku: 'apple', qty: 1 }] }))).body.id
  assert.equal(Number(after), Number(before) + 1)
})

test('unknown routes and wrong methods -> 404 no route', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/x']]) {
    const r = await json(await fetch(base + path, { method }))
    assert.equal(r.status, 404, `${method} ${path}`)
    assert.deepEqual(r.body, { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const r = await json(await fetch(`${base}/orders/zzz?x=1`))
  assert.deepEqual(r.body, { error: 'not found' })
})
